// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2004, "6-7", [{"author":"К. Кноп и И. Рубанов","question":"Женя, Саша, Шура, Маша и Валя были в гостях у Коли. Шура ушла рано, остальные засиделись допоздна. Саша остался ночевать у Коли, за Машей и Женей пришла старшая сестра и отвела обеих домой, а Валя вернулся домой сам, потому что жил в соседнем подъезде. Сколько девочек было в гостях у Коли?","choices":["одна","две","три","четыре","пять"],"key":"В","review":["Что выдают формы слов","Шура «ушла», а сестра отвела «обеих», то есть Машу и Женю. Эти формы относятся к девочкам.","Саша «остался», Валя «вернулся сам». Они мальчики, а девочек было трое."]},{"author":"И. Рубанов","question":"Из каких пяти идущих подряд букв русского алфавита можно, записав их в другом порядке, составить какое-нибудь пятибуквенное русское слово?","choices":["рстуф","опрст","клмно","гдеёж","абвгд"],"key":"Б","review":["Перестановка букв алфавита","Поищи слово, в котором используются все пять букв и каждая только один раз.","Из о, п, р, с, т складывается «спорт». Эти пять букв идут подряд в алфавите."]},{"author":"Ю. Халеева","question":"Заполните пропуски во фразе: ... такое съесть, ... похудеть?","choices":["чтобы, чтобы","что бы, что бы","чтобы, что бы","что бы, чтобы","среди вариантов (А)–(Г) нет правильного"],"key":"Г","review":["Местоимение и союз","В вопросе «что бы такое съесть» «что» спрашивает о предмете, а «бы» — отдельная частица.","Вторая часть называет цель: «чтобы похудеть». Здесь «чтобы» — слитный союз."]},{"author":"Н. Валеева","question":"В каком из этих слов буква г произносится не так, как в остальных?","choices":["бог","рог","стог","мог","порог"],"key":"А","review":["Звук на конце слова","В словах «рог», «стог», «мог» и «порог» конечный [г] оглушается в [к].","Слово «бог» традиционно произносится с конечным [х]. Оно выпадает из общего ряда."]},{"author":"Л. Фёдорова","question":"Несмотря на «противоположные» приставки, слова в одной из этих пар означают одно и то же. В какой?","choices":["развернуть — завернуть","раскрыть — закрыть","разделать — заделать","раздумать — задумать","рассмеяться — засмеяться"],"key":"Д","review":["Когда начинается смех","«Рассмеяться» и «засмеяться» оба обозначают начало смеха.","В других парах приставки меняют значение, иногда на противоположное: «раскрыть — закрыть»."]},{"author":"И. Иткин","question":"Учитель спросил учеников, какие они знают русские пословицы и поговорки.\nАндрей сказал: Чем дальше влез, тем ближе вылез.\nБоря сказал: В огороде бузина, а в Киеве — дядька.\nВитя сказал: Тише едешь — дальше будешь.\nГаля сказала: Любишь кататься, люби и саночки возить.\nДаша сказала: Один с сошкой, семеро с ложкой.\nКто из учеников не справился с заданием?","choices":["Андрей","Боря","Витя","Галя","Даша"],"key":"А","review":["Переиначенная пословица","Боря, Витя, Галя и Даша назвали известные пословицы без замены слов.","Андрей переделал «Чем дальше в лес, тем больше дров». Его фраза похожа по звучанию, но это уже не исходная пословица."]},{"author":"Е. Холодова","question":"Формой какого наклонения может быть слово положите?","choices":["изъявительного","повелительного","условного","изъявительного и повелительного","повелительного и условного"],"key":"Г","review":["Одинаковое написание","«Вы поло́жите книгу на стол» сообщает о будущем действии и стоит в изъявительном наклонении.","«Положи́те книгу на стол!» выражает просьбу или приказ. Так выглядит форма повелительного наклонения."]},{"author":"Е. Муравенко","question":"В четырёх ребусах зашифровано одно и то же слово, а в одном — другое. В каком?","choices":["Ребус А","Ребус Б","Ребус В","Ребус Г","Ребус Д"],"key":"Г","review":["Что скрыто в ребусе","В ребусе А читаем «под С — та» и «в К — а». Получается «подставка», как и в Б, В и Д.","В ребусе Г начало — «под Г — О», после запятой от «сто» остаётся «то», а «в К — а» даёт конец. Получается «подготовка»."],"figure":{"options":[{"src":"assets/medvezhonok/2004/6-7-08-rebus-1.webp","description":"Буквы ТА под С и А внутри большой К.","pixelWidth":147,"pixelHeight":82},{"src":"assets/medvezhonok/2004/6-7-08-rebus-2.webp","description":"Буквы С в большой Д, миска, буквы В и А.","pixelWidth":351,"pixelHeight":84},{"src":"assets/medvezhonok/2004/6-7-08-rebus-3.webp","description":"Курсивная П, единица с запятыми, ТА и А внутри К.","pixelWidth":286,"pixelHeight":81},{"src":"assets/medvezhonok/2004/6-7-08-rebus-4.webp","description":"Под О стоит Г, запятая перед числом 100, А внутри большой К.","pixelWidth":193,"pixelHeight":76},{"src":"assets/medvezhonok/2004/6-7-08-rebus-5.webp","description":"Поезд с номерами 1, 2, 5, число 100 с запятой, А внутри К и ещё одна А.","pixelWidth":408,"pixelHeight":88}]}},{"author":"И. Рубанов","question":"Какое из этих слов нельзя вписать вместо многоточия во фразу: Чинить ...?","choices":["карандаши","здания","препятствия","телевизоры","электропроводку"],"key":"Б","review":["Как сочетается «чинить»","Карандаши старым словоупотреблением можно «чинить», то есть заострять. Телевизор и проводку чинят, когда ремонтируют.","В сочетании «чинить препятствия» смысл «создавать помехи». Здания обычно ремонтируют; «чинить здания» среди предложенных сочетаний не принято."]},{"author":"Н. Валеева","question":"В каком из перечисленных слов -ся имеет не то значение, что в остальных?","choices":["подниматься","кататься","дразниться","защищаться","наклоняться"],"key":"В","review":["Кому направлено действие","Подниматься, кататься, защищаться и наклоняться можно самому. Действие относится к самому действующему лицу.","Тот, кто дразнится, направляет действие на других: он дразнит кого-то. Здесь -ся передаёт привычное или повторяемое действие."]},{"author":"С. Бурлак","question":"Какое слово написано с ошибкой?","choices":["бреют","клеют","реют","сеют","тлеют"],"key":"Б","review":["Окончания настоящего времени","«Бреют», «реют», «сеют» и «тлеют» имеют окончание -ют.","Глагол «клеить» относится ко второму спряжению. Верная форма — «клеят»."]},{"author":"Е. Муравенко","question":"Какое из этих прилагательных по составу отличается от остальных?","choices":["плоский","броский","веский","пермский","майский"],"key":"А","review":["Корень или суффикс","В «броский» и «веский» к корням прибавлен суффикс -к-, а в «пермский» и «майский» — -ск-.","В «плоский» сочетание плоск- целиком относится к корню; сравни «плоскость»."]},{"author":"Л. Фёдорова","question":"Сколько исторически различных (то есть таких, которые различны не только в современном языке, но и по своему происхождению) корней во фразе: Четыре чёрненьких чумазеньких чертёнка чертили чёрными чернилами чертёж?","choices":["7","6","5","4","3"],"key":"В","review":["Корни в скороговорке","«Четыре» даёт один корень, «чёрненьких», «чёрными» и «чернилами» — другой, а «чумазеньких» — третий, связанный с «мазать».","«Чертёнок» связан с «чёртом». «Чертили» и «чертёж» связаны с «чертой»: это отдельный исторический корень. Всего пять."]},{"author":"Е. Дмитриева","question":"В каком предложении слово весело является именем прилагательным?","choices":["Детям весело.","Дитя весело.","Весело кататься с горы.","Дитя весело смеётся.","Дети весело катаются с горы"],"key":"Б","review":["Свойство или образ действия","В «дитя весело» слово описывает состояние самого дитяти и согласуется с ним в среднем роде: дитя какое? — весело.","В остальных примерах «весело» описывает действие или безличное состояние. Это не форма прилагательного."]},{"author":"Л. Фёдорова","question":"Из пяти приведённых ниже слов четыре образованы одним и тем же способом, а оставшееся — нет. Найдите это слово.","choices":["страшила","громила","верзила","кутила","зубрила"],"key":"В","review":["От какого слова образовано","«Страшила», «громила», «кутила» и «зубрила» связаны с глаголами «страшить», «громить», «кутить» и «зубрить».","«Верзила» означает высокого нескладного человека и не строится по модели «тот, кто выполняет названное действие»."]},{"author":"Л. Фёдорова","question":"Какое слово лишнее по смыслу?","choices":["будущий","следующий","грядущий","предыдущий","предстоящий"],"key":"Г","review":["Порядок во времени","«Будущий», «следующий», «грядущий» и «предстоящий» указывают на то, что будет потом.","«Предыдущий» называет то, что было раньше. Направление во времени противоположное."]},{"author":"Ю. Халеева","question":"Вот цитата из воспоминаний Людмилы Штерн о писателе Сергее Довлатове:\n— Нет, нет, какие могут быть звонки? Скоро утро.\n— Когда я хочу разговаривать с друзьями, время суток не ...,\n— сказал Довлатов, заметно мрачнея.\nКакой текст мы заменили многоточием?","choices":["чего не значит","чему не мешает","имеет роли","имеет значения","играет значения"],"key":"Г","review":["Устойчивое отрицание","Говорят «время суток не имеет значения». Это означает, что время для разговора несущественно.","Есть также оборот «не играет роли». Варианты «не имеет роли» и «не играет значения» смешивают два оборота."]},{"author":"И. Иткин и Е. Холодова","question":"Даны слова есть, лезть, весть, честь. Верно ли, что любые два из них состоят из одинакового числа звуков и при этом различаются только одним звуком? Если нет, то какое из них надо вычеркнуть, чтобы это стало верно?","choices":["верно","нет, надо вычеркнуть слово есть","нет, надо вычеркнуть слово лезть","нет, надо вычеркнуть слово весть","нет, надо вычеркнуть слово честь"],"key":"А","review":["Начальный согласный","«Есть» начинается с [й’], «лезть» — с [л’], «весть» — с [в’], «честь» — с [ч’].","После начального звука во всех словах слышно [эс’т’]: в слове «лезть» з оглушается. Поэтому любая пара различается ровно одним звуком."]},{"author":"И. Иткин","question":"Сколько в русском языке предлогов, союзов и местоимений, состоящих всего из одной буквы?","choices":["4 предлога, 1 союз и 1 местоимение","4 предлога, 2 союза и 1 местоимение","5 предлогов, 1 союз и 1 местоимение","5 предлогов, 2 союза и 1 местоимение","5 предлогов, 2 союза и 2 местоимения"],"key":"Г","review":["Слова из одной буквы","Однобуквенные предлоги — в, к, о, с, у. Их пять.","Союзы — а и и, местоимение — я. Получается пять, два и один."]},{"author":"Е. Муравенко","question":"Сколько разных падежей представлено в следующих словосочетаниях: подойти к дому, съесть грушу, прыгнуть с разбегу, выпить чаю, гулять в саду, сидеть с краю, идти по мосту, хранить на шкафу, отвечать учителю?","choices":["два","три","четыре","пять","шесть"],"key":"В","review":["Падежи и одинаковый звук","«К дому», «по мосту» и «учителю» — дательный, «грушу» — винительный.","«С разбегу», «чаю» и «с краю» — формы родительного, «в саду» и «на шкафу» — предложного. Всего четыре."]},{"author":"И. Иткин","question":"Как в России в XIX веке нельзя было обратиться ни к какому высокопоставленному лицу?","choices":["Ваша милость","Ваша светлость","Ваша честность","Ваша честь","Ваше высокопреосвященство"],"key":"В","review":["Как обращались к титулованным","«Ваша милость», «Ваша светлость» и «Ваше высокопреосвященство» — формы учтивого исторического обращения. Встречалось и «Ваша честь».","«Ваша честность» не служило установленным обращением к высокопоставленному лицу."]},{"author":"Е. Дмитриева","question":"В каком стихотворном отрывке обозначенное ударение не соответствует современной литературной норме?","choices":["Ты режешь круг, сечёшь овал,\nТебе не нравится давно,\nЧто горизонт избалова́л\nМоё открытое окно ... (Н. Матвеева)","Камнями плоскими лежат\nЗелёно-каменные ка́мбалы ... (С. Кирсанов)","Безмерный круг незавершённых дел,\nСоздания, не знавшие рожденья …\nЗдесь всё, что я посмел и не сумел, —\nЖеланья, замыслы и намере́нья ... (С. Наровчатов)","Сын четвёртый, Никанор, —\nПо профессии шофё́р ... (М. Владимов)","От ско́льких людей я завишу:\nОт тех, кто посеял зерно,\nОт тех, кто чинил мою крышу,\nКто вставил мне стёкла в окно ... (Н. Асеев)"],"key":"В","review":["Словарное ударение","По современной норме говорят «наме́ренье», как и «наме́рение».","В строке Наровчатова стоит «намере́нья»: поэт перенёс ударение ради рифмы с «рожденья». Остальные ударения допустимы."]},{"author":"И. Рубанов","question":"Какие три из четырёх имён: Юрий, Георгий, Егор, Игорь — имеют общее происхождение?","choices":["Юрий, Георгий, Егор","Георгий, Егор, Игорь","Юрий, Георгий, Игорь","Юрий, Егор, Игорь","никакие"],"key":"А","review":["Три формы имени","Георгий — имя греческого происхождения. В русском языке с ним исторически связаны Юрий и Егор.","Игорь имеет скандинавское происхождение. Сходство звучания не делает его вариантом Георгия."]},{"author":"Е. Дмитриева","question":"В каком предложении нет ошибок?","choices":["На складе осталось двое пар сапог.","У магазина томились трое помятых личностей.","В спектакле занято четверо актрис.","В семье было пятеро детей.","По обоим сторонам дороги зеленеют деревья"],"key":"Г","review":["Употребление собирательных","Собирательные числительные употребляются со словом «дети»: «пятеро детей» грамматически верно.","В остальных фразах нужны «две пары», «три личности», «четыре актрисы» и «по обеим сторонам»."]},{"author":"Н. Валеева","question":"Сколько из перечисленных существительных относятся к мужскому роду: аэрозоль, бандероль, картофель, метель, мозоль, ноль, шинель, шрапнель?","choices":["пять","четыре","три","два","одно"],"key":"В","review":["Род слов на мягкий знак","В мужском роде говорят «этот аэрозоль», «этот картофель» и «этот ноль».","Бандероль, метель, мозоль, шинель и шрапнель — женского рода. Мужских три."]},{"author":"Н. Валеева","question":"Сколько слов из этого списка содержат удвоенное с: рас…чёт, рас…честь, рас…читать, рас…чётливый, рас…читывать?","choices":["одно","два","три","четыре","пять"],"key":"Б","review":["Сколько букв на стыке","В «рассчитать» и «рассчитывать» одна с относится к приставке рас-, а другая открывает часть -счит-.","В «расчёт», «расчесть» и «расчётливый» после приставки сразу идёт ч. Две с нужны в двух словах."]},{"author":"И. Рубанов","question":"Попыхивая ц...гаркой, ц...ган ц...дил пойло в ц...нковое корыто. «Ц...ц, куриц...н сын! — ц...кнул он на подбежавшего ц...пленка, — ещё получишь свою порц...ю». Сколько в этом тексте стёрто букв ы?","choices":["ни одной","четыре","пять","шесть","восемь"],"key":"В","review":["Пропуски после «ц»","Ы нужно в словах «цыган», «цыц», «курицын», «цыкнул» и «цыплёнка».","Остальные пропуски заполняют и или е: «цигаркой», «цедил», «цинковое», «порцию»."]},{"author":"Н. Валеева и К. Кноп","question":"Коренной житель Америки — индеец. А коренная жительница?","choices":["индейка","индеанка","индийка","индианка","среди ответов (А)–(Г) нет правильного"],"key":"Г","review":["Женский род названия народа","«Индейка» — птица, «индийка» — жительница Индии.","Коренную жительницу Америки называют «индианка». Это слово исторически соотносится с «индеец»."]},{"author":"П. Аркадьев","question":"Даны предложения на японском языке и их переводы на русский язык:\nгакусэй-га ёму ‘студент читает’\nсэнсэй-га о-каки-ни нару ‘учитель пишет’\nмусуко-га каку ‘мальчик пишет’\nбутё-га о-ханаси-ни нару ‘начальник говорит’\nКак правильно перевести на японский язык: студент говорит; начальник читает?","choices":["гакусэй-га ханасу, бутё-га ёму","гакусэй-га о-ханаси-ни нару, бутё-га о-ёми-ни нару","гакусэй-га о-ханаси-ни нару, бутё-га ёму","гакусэй-га ханасу, бутё-га о-ёми-ни нару","гакусэй-га ханаси, бутё-га о-ёму-ни нару"],"key":"Г","review":["Две формы японского глагола","О студенте и мальчике говорят простыми формами «ёму» и «каку». Для учителя и начальника употребляют уважительную конструкцию «о-…-ни нару».","«Студент говорит» требует ханасу, «начальник читает» — о-ёми-ни нару. С подлежащими это вариант Г."]},{"author":"Е. Муравенко","question":"У некоторых существительных совпадают формы разных падежей. Например, форму стол можно понять и как именительный, и как винительный падеж единственного числа. Рассмотрим три склонения. В каких из них встречаются существительные, у которых в единственном числе совпадают три падежные формы?","choices":["в 1-ом, 2-ом и 3-ем склонениях","в 1-ом и 3-ем склонениях","только в 1-ом склонении","только во 2-ом склонении","только в 3-ем склонении"],"key":"А","review":["Три падежа и одна форма","В первом склонении «станции» может быть родительным, дательным или предложным. В третьем то же верно для формы «ночи».","Во втором совпадение видно в «много снегу», «по снегу», «в снегу» — родительном, дательном и предложном. Таким образом, подходят все три склонения."]}], {"year":2004,"grade":"6-7","tasksFile":"6-7.pdf","answersFile":"6-7-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2004.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
